 {page==='reports'&&<><section className="card"><h2 className="font-bold mb-3">Sales Reports</h2><div className="grid grid-cols-2 gap-2">{[["Today's Sales",liveDaily.find(x=>x.key===currentDay),'daily',currentDay],['This Month',liveMonthly.find(x=>x.key===currentMonth),'monthly',currentMonth]].map(([label,rec,kind,key])=><div className="bg-slate-100 p-3 rounded-xl" key={label}><div className="flex items-center justify-between gap-2"><p className="muted">{label}</p>{isAdmin&&<button type="button" className="text-xs font-bold text-brand-700 underline" onClick={()=>resetReportPeriod(kind,key)}>Reset to zero</button>}</div><p className="font-extrabold text-xl break-all">{cash(rec?.total||0)}</p><p className="muted">{rec?.count||0} transactions</p></div>)}</div></section><SalesPeriodReport title="Daily Sales" rows={daily} shownRows={dailyPageRows} page={activeDailyPage} pageSize={dailyPageSize} pageCount={dailyPageCount} onPageChange={setDailySalesPage} selected={selectedDailyPeriods} setSelected={setSelectedDailyPeriods} onDelete={deleteReportPeriods} onExport={exportReportPeriods} kind="daily" canDelete={isAdmin}/><SalesPeriodReport title="Monthly Sales" rows={monthly} shownRows={monthlyPageRows} page={activeMonthlyPage} pageSize={monthlyPageSize} pageCount={monthlyPageCount} onPageChange={setMonthlySalesPage} selected={selectedMonthlyPeriods} setSelected={setSelectedMonthlyPeriods} onDelete={deleteReportPeriods} onExport={exportReportPeriods} kind="monthly" canDelete={isAdmin}/></>}
 {page==='history'&&<section className="card"><div className="flex justify-between items-center mb-3"><h2 className="font-bold text-lg">Sales History</h2><span className="chip">{data.sales.length} receipts</span></div>{data.sales.length===0?<p className="muted py-5">No completed sales.</p>:<><div className="flex flex-wrap gap-2 items-center justify-between bg-slate-100 p-2 rounded-xl mb-3"><label className="!mb-0 flex items-center gap-2"><input type="checkbox" className="w-5 h-5" checked={salesHistoryRows.length>0&&salesHistoryRows.every(s=>selectedSales.includes(s.id))} onChange={e=>setSelectedSales(current=>e.target.checked?[...new Set([...current,...salesHistoryRows.map(s=>s.id)])]:current.filter(id=>!salesHistoryRows.some(s=>s.id===id)))}/> Select page</label><span className="muted">{selectedSales.length} selected</span><div className="flex gap-2"><button type="button" className="btn2 !min-h-10 !py-2" disabled={!selectedSales.length} onClick={()=>exportSales(selectedSales)}><Download size={16} className="inline mr-1"/>Export selected</button>{isAdmin&&<button type="button" className="text-red-600 font-bold disabled:opacity-30" disabled={!selectedSales.length} onClick={()=>deleteSales(selectedSales)}>Delete selected</button>}</div></div>{salesHistoryRows.map(s=><div key={s.id} className="rounded-xl border mb-3 overflow-hidden"><div className="p-3 flex items-center gap-3"><input type="checkbox" className="!w-5 !h-5" aria-label={`Select receipt ${s.bill}`} checked={selectedSales.includes(s.id)} onChange={e=>setSelectedSales(a=>e.target.checked?[...a,s.id]:a.filter(x=>x!==s.id))}/><button className="flex-1 text-left min-w-0" onClick={()=>setOpenSale(openSale===s.id?'':s.id)}><b>{s.bill}</b><p className="muted">{formatDhakaDateTime(s.createdAt)}</p></button><b className="whitespace-nowrap">{cash(s.total)}</b><button type="button" aria-label={`Export receipt ${s.bill} as CSV`} className="rounded-lg p-2 text-brand-700 hover:bg-brand-50" onClick={()=>exportSales([s.id])}><Download size={17}/></button><button type="button" aria-label={`Toggle receipt ${s.bill}`} onClick={()=>setOpenSale(openSale===s.id?'':s.id)}><ChevronDown size={20}/></button></div>{openSale===s.id&&<div className="bg-slate-50 p-3 border-t"><Invoice sale={s} showQr={false}/><div className="grid grid-cols-3 gap-2 mt-3"><button className="btn2 !px-1 text-xs" onClick={()=>printReceipt(s)}>Print</button><button type="button" className="btn2 !px-1 text-xs" onClick={()=>sendReceiptWhatsApp(s)}><MessageCircle size={15} className="inline mr-1"/>WhatsApp</button>{isAdmin&&<button className="btn2 !px-1 text-xs text-red-600" onClick={()=>deleteSales([s.id])}>Delete</button>}</div></div>}</div>)}{data.sales.length>salesHistoryPageSize&&<div className="mt-3 flex items-center justify-between gap-3"><span className="muted">Showing {activeSalesHistoryPage*salesHistoryPageSize+1}–{Math.min((activeSalesHistoryPage+1)*salesHistoryPageSize,data.sales.length)} of {data.sales.length} receipts</span><div className="flex gap-2"><button type="button" className="btn2 !min-h-10 !py-2" disabled={activeSalesHistoryPage===0} onClick={()=>setSalesHistoryPage(activeSalesHistoryPage-1)}>Previous</button><button type="button" className="btn2 !min-h-10 !py-2" disabled={activeSalesHistoryPage>=salesHistoryPageCount-1} onClick={()=>setSalesHistoryPage(activeSalesHistoryPage+1)}>Next</button></div></div>}</>}</section>}
