function groupSales(sales,kind,reportResets={}){let map=new Map();for(let s of sales){let key=bangDate(s.createdAt);if(kind==='monthly')key=key.slice(0,7);const resetAt=reportResets[`${kind}:${key}`];if(resetAt&&Date.parse(s.createdAt)<Date.parse(resetAt))continue;let prev=map.get(key)||{key,total:0,count:0};prev.total+=numeric(s.total);prev.count++;map.set(key,prev)}for(const period of Object.keys(reportResets)){const prefix=`${kind}:`;if(period.startsWith(prefix)){const key=period.slice(prefix.length);if(!map.has(key))map.set(key,{key,total:0,count:0})}}return [...map.values()].sort((a,b)=>b.key.localeCompare(a.key))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function downloadCSV(filename,rows){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+rows.map(r=>r.map(q).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function parseCSV(text){let rows=[],field='',row=[],inside=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(inside&&text[i+1]==='"'){field+='"';i++}else inside=!inside}else if(c===','&&!inside){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!inside){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);field='';row=[]}else field+=c}row.push(field);if(row.some(v=>v.trim()))rows.push(row);let heads=rows.shift()||[];return rows.map(r=>Object.fromEntries(heads.map((h,i)=>[h.replace(/^\ufeff/,''),r[i]||''])))}
